-- Employee Warning Notice -- authored as a DRAFT, 2026-11-14. Replaces the
-- JotForm-filled paper Employee Warning Notice.
-- APPLIED via psql 2026-11-14: form_id 739c8dbd-5e54-4182-a29e-3edc47a18962 (draft, unpublished).
-- Built by scripts/gen-warning-notice.ts (strict + draft validated), in TEST
-- mode: every email goes to josh.copp@splashcarwashes.com. To go live,
-- regenerate with LIVE=1 (site HRT + RM + supervisor; employee copy to the
-- employee's email when given), re-run this file with that schema, publish.
--
-- Re-runnable: upserts the forms row, creates a draft version only when there
-- is none, otherwise overwrites the existing draft schema.
--
--   slug employee-warning-notice   audience link-only   34 fields   2 email steps
--
-- CONFIDENTIAL -- NOT SITE-SCOPED (same as Pay Change): scope_location_field_key
-- is the sentinel 'none:confidential' so publish neither injects nor designates
-- a site_number scope field; submissions are readable only by admins and the
-- people the workflow routes to, until PLAN_FORMS_PERSONNEL.md phase 3.
--
-- notify_webhook = false: a personnel record must not go to the generic
-- Power Automate submission webhook.

insert into public.forms
  (slug, title, description, audience, status, notify_webhook,
   turnstile_required, success_message, created_by, last_edited_by)
values
  ('employee-warning-notice',
   'Employee Warning Notice',
   'Write up an employee warning with them present. They sign on the tablet and get a copy with the Notice of Negative Information.',
   'link-only',
   'draft',
   false,
   false,
   'Thanks - the warning notice and the Notice of Negative Information have been sent to HR, the RM and you. If you chose to print the employee''s copy, print it from that email and hand it to them in a sealed envelope today.',
   'f42882fd-ee5a-433e-b10b-713d5dff8a89',
   'f42882fd-ee5a-433e-b10b-713d5dff8a89')
on conflict (slug) do update
  set title = excluded.title,
      description = excluded.description,
      audience = excluded.audience,
      notify_webhook = excluded.notify_webhook,
      turnstile_required = excluded.turnstile_required,
      success_message = excluded.success_message,
      last_edited_at = now();

update public.forms set scope_location_field_key = 'none:confidential'
 where slug = 'employee-warning-notice' and scope_location_field_key is distinct from 'none:confidential';

